using System.Globalization;
using System.Resources;

namespace MiruPlay.Windows.Services;

/// <summary>
/// Localised UI strings from Resources/Strings*.resx (generated by
/// tools/i18n/build.js). Falls back to zh-CN, then to the key itself.
/// The active culture follows <see cref="AppLocale"/> (applied at startup
/// and on change); WPF static bindings resolve at load, so a language
/// change takes effect after restart.
/// </summary>
public static class AppStrings
{
    private static readonly ResourceManager Manager = new(
        "MiruPlay.Windows.Resources.Strings", typeof(AppStrings).Assembly);

    private static readonly CultureInfo Fallback = CultureInfo.GetCultureInfo("zh-CN");

    public static string Get(string key, params object?[] args)
    {
        var value = Manager.GetString(key, CultureInfo.CurrentUICulture)
            ?? Manager.GetString(key, Fallback)
            ?? key;
        return args.Length == 0 ? value : string.Format(CultureInfo.CurrentCulture, value, args);
    }
}
